### 3. script.js
```javascript
// 游戏核心逻辑
class Game {
  constructor() {
    this.grid = Array(25).fill(0);
    this.score = 0;
    this.maxScore = 0;
    this.won = false;
    this.lose = false;
    this.generateGrid();
    this.render();
  }

  // 初始化游戏
  generateGrid() {
    this.grid = Array(25).fill(0);
    this.grid[10] = 2;
    this.grid[15] = 4;
    this.placeRandom();
  }

  // 移动逻辑
  move(direction) {
    let moved = false;
    let newGrid = new Array(25).fill(0);

    if (direction === 'up') {
      for (let i = 0; i < 25; i++) {
        if (i % 4 === 0 && i < 20) {
          if (this.grid[i] !== 0) {
            newGrid[i] = this.grid[i];
          }
        } else {
          newGrid[i] = this.grid[i];
          // 合并相同数字
          if (this.grid[i] === this.grid[i-1] || this.grid[i] === this.grid[i+1]) {
            let val = this.grid[i] === this.grid[i-1] ? this.grid[i] : this.grid[i];
            this.grid[i] = val;
            this.grid[i-1] = val * 2;
            this.grid[i+1] = val;
          }
        }
      }
    } else if (direction === 'down') {
      for (let i = 0; i < 25; i++) {
        if (i % 4 === 0 && i < 20) {
          if (this.grid[i] !== 0) {
            newGrid[i] = this.grid[i];
          }
        } else {
          newGrid[i] = this.grid[i];
          // 合并相同数字
          if (this.grid[i] === this.grid[i-1] || this.grid[i] === this.grid[i+1]) {
            let val = this.grid[i] === this.grid[i-1] ? this.grid[i] : this.grid[i];
            this.grid[i] = val;
            this.grid[i-1] = val * 2;
            this.grid[i+1] = val;
          }
        }
      }
    }

    // 更新网格
    this.grid = newGrid;

    // 判断游戏结束
    if (!this.canMove('up') && !this.canMove('down') && !this.canMove('left') && !this.canMove('right')) {
      this.gameOver();
    }
  }

  // 渲染界面
  render() {
    const grid = document.getElementById('game-grid');

    for (let i = 0; i < 25; i++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.style.gridRow = i / 4 + 1;
      cell.style.gridColumn = (i % 4) + 1;

      if (this.grid[i] !== 0) {
        cell.textContent = this.grid[i];
        cell.style.backgroundColor = this.getComputedStyleColor(this.grid[i]);
      }
      grid.appendChild(cell);
    }

    // 更新分数
    this.updateScore();

    // 更新状态
    this.updateStatus();
    this.renderEndGame();
  }

  // 游戏结束处理
  gameOver() {
    this.won = false;
    this.lose = true;
    this.updateStatus();
    this.renderEndGame();
  }

  // 更新状态
  updateStatus() {
    const status = document.getElementById('status');
    if (this.won) status.textContent = '🎉 2048！胜利！';
    else if (this.lose) status.textContent = '💀 失败！';
    else status.textContent = '🎮 开始游戏';
  }

  // 渲染结束状态
  renderEndGame() {
    const status = document.getElementById('status');
    if (this.won) {
      status.innerHTML = '<span style="color: var(--winner-color)">🎉 2048！胜利！</span>';
      status.innerHTML += '<span style="color: var(--winner-color)">🎉 2048！胜利！</span>'
    } else if (this.lose) {
      status.innerHTML = '<span style="color: var(--lost-color)">💀 失败！</span>';
    }
  }

  // 获取颜色
  getComputedStyleColor(val) {
    return {
      2: 'var(--gold)',
      4: 'var(--gold)',
      8: 'var(--gold)',
      16: 'var(--gold)',
      32: 'var(--gold)',
      64: 'var(--gold)',
      128: 'var(--gold)',
      256: 'var(--gold)',
      512: 'var(--gold)',
      1024: 'var(--gold)',
      2048: 'var(--gold)',
      0: 'var(--cell-bg)'
    }[val] || 'var(--cell-bg)';
  }

  // 检查是否可以移动
  canMove(direction) {
    let blocked = false;
    if (direction === 'up' || direction === 'down') {
      for (let i = 0; i < 25; i++) {
        if (!this.canMove(this.grid[i])) {
          blocked = true;
          break;
        }
      }
    }
    return !blocked;
  }

  // 检查是否可以合并
  canMerge(grid) {
    for (let i = 0; i < 25; i++) {
      if (grid[i] === 0) continue;
      if (grid[i-1] && grid[i-1] === grid[i]) {
        return true;
      }
      if (grid[i-3] && grid[i-3] === grid[i]) {
        return true;
      }
    }
    return false;
  }

  // 更新分数
  updateScore() {
    const score = document.getElementById('score');
    score.textContent = this.score.toLocaleString();
    if (this.score > this.maxScore) {
      this.maxScore = this.score;
      score.textContent = '🏆 ' + this.maxScore.toLocaleString() + ' 分';
    }
  }

  // 开始游戏按钮处理
  startGame() {
    this.won = false;
    this.lose = false;
    this.score = 0;
    this.maxScore = 0;
    this.grid = Array(25).fill(0);
    this.grid[10] = 2;
    this.grid[15] = 4;
    this.placeRandom();
    this.render();
  }

  // 放置随机方块
  placeRandom() {
    const valid = [];
    for (let i = 0; i < 25; i++) {
      if (this.grid[i] === 0) valid.push(i);
    }
    if (valid.length > 0) {
      const r = Math.floor(Math.random() * valid.length);
      this.grid[valid[r]] = Math.random() > 0.9 ? 2 : 4;
      this.placeRandom();
    }
  }
}

